import hashlib,json
from pathlib import Path
H=Path(__file__).resolve().parent;B=H.parent
for x in ('controls','evaluation'):(H/x).mkdir(parents=True,exist_ok=True)
def write(p,x):p.write_text(json.dumps(x,indent=2)+'\n',encoding='utf8')
refs=['https://iupac.qmul.ac.uk/BlueBook/P9.html#P-93.1','https://iupac.qmul.ac.uk/BlueBook/P7.html','https://iupac.qmul.ac.uk/BlueBook/P8.html','https://iupac.qmul.ac.uk/BlueBook/P1.html#P-14.7']
def claim(i,name,dim,smiles=None,state='EXACT',role='IDENTITY_ASSERTION',verified=True,origin='SOURCE_PROVIDED',framework=None):
 return {'id':i,'name':name,'dimension':dim,'state':state,'smiles':smiles,'framework':framework or smiles,'role':role,'role_established':verified,'origin':origin,'dependencies':[],'basis':'RULE_ESTABLISHED' if smiles or state=='UNSPECIFIED' else 'UNVERIFIED'}
def case(i,name,claims,candidate,dim,relations,outcome,why):
 return {'id':i,'description':name,'claims':claims,'candidate':candidate,'required_dimensions':[dim],'expected_relationships':relations,'expected_result':outcome,'chemical_justification':why,'references':refs,'review_status':'CHEMICAL_REVIEW_PENDING','evidence_note':'Name-to-graph semantics are explicitly annotated provisional rule-grounded inputs, not inferred by the reconciliation engine.'}
R='CC[C@H](O)C';S='CC[C@@H](O)C';U='CCC(O)C';nit='O=[N+]([O-])c1ccccc1'
dev=[
case('D01','ethanol / ethyl alcohol',[claim('a','ethanol','constitution','CCO'),claim('b','ethyl alcohol','constitution','OCC')],'CCO','constitution',['EXACT_COMPATIBLE','EXACT_COMPATIBLE'],'RECONCILED_COMPATIBLE','Compatible constitutional assertions, preserved provenance.'),
case('D02','specified stereoisomer',[claim('a','specified butan-2-ol','stereochemistry',R)],R,'stereochemistry',['EXACT_COMPATIBLE'],'RECONCILED_COMPATIBLE','Same explicitly specified stereo graph.'),
case('D03','unspecified stereo alone',[claim('a','butan-2-ol','stereochemistry',None,'UNSPECIFIED',framework=U)],R,'stereochemistry',['BROADER_THAN_CANDIDATE'],'RECONCILIATION_UNRESOLVED','Explicitly annotated unspecified stereo does not select an enantiomer.'),
case('D04','broad and specific compatible',[claim('a','butan-2-ol','stereochemistry',None,'UNSPECIFIED',framework=U),claim('b','specified butan-2-ol','stereochemistry',R)],R,'stereochemistry',['BROADER_THAN_CANDIDATE','EXACT_COMPATIBLE'],'RECONCILED_COMPATIBLE','Specific source claim supplies stereo; broad claim does not conflict.'),
case('D05','opposite stereo',[claim('a','opposite butan-2-ol','stereochemistry',S)],R,'stereochemistry',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Opposite configurations are distinct, not a broad claim.'),
case('D06','constitution isomer',[claim('a','dimethyl ether','constitution','COC')],'CCO','constitution',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Constitution differs.'),
case('D07','acid / conjugate base',[claim('a','benzoate','protonation_charge','O=C([O-])c1ccccc1')],'O=C(O)c1ccccc1','protonation_charge',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Common framework, proton and net charge change.'),
case('D08','equivalent nitro representation',[claim('a','nitrobenzene','protonation_charge',nit)],'[O-][N+](=O)c1ccccc1','protonation_charge',['EXACT_COMPATIBLE'],'RECONCILED_COMPATIBLE','Equivalent nitro electron representation.'),
case('D09','neutral / zwitterionic glycine graphs',[claim('a','explicit neutral glycine graph','protonation_charge','NCC(=O)O')],'[NH3+]CC(=O)[O-]','protonation_charge',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Explicit graphs differ in H/charge positions; unqualified name glycine is not adjudicated.'),
case('D10','specified hydration composition',[claim('a','explicit ethanol water adduct graph','hydration_solvation','CCO.O')],'CCO','hydration_solvation',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Control is explicit component composition, not solid-state hydrate identification.'),
case('D11','free base / hydrochloride',[claim('a','explicit methylammonium chloride graph','components','C[NH3+].[Cl-]')],'CN','components',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Component identity differs; salt not stripped.'),
case('D12','uninterpreted active alias',[claim('a','ethanol','constitution','CCO'),claim('b','unparseable alias','constitution',None,'UNKNOWN')],'CCO','constitution',['EXACT_COMPATIBLE','UNKNOWN'],'RECONCILIATION_UNRESOLVED','Active alias uncertainty blocks record resolution.'),
case('D13','documented search keyword',[claim('a','ethanol','constitution','CCO'),claim('b','solvent search keyword','constitution',None,'UNKNOWN','SEARCH_LABEL')],'CCO','constitution',['EXACT_COMPATIBLE','NON_BINDING_METADATA'],'RECONCILED_COMPATIBLE','Role is explicitly documented; metadata is not an identity assertion.'),
case('D14','identifier without correspondence',[claim('a','external identifier','constitution',None,'UNKNOWN')],'CCO','constitution',['UNKNOWN'],'RECONCILIATION_UNRESOLVED','An identifier without validated identity mapping does not establish structure.'),
case('D15','specific source broader candidate',[claim('a','specified stereo','stereochemistry',R)],U,'stereochemistry',['NARROWER_THAN_CANDIDATE'],'RECONCILIATION_UNRESOLVED','Candidate stereo omitted; no exact identity.'),
case('D16','explicit tautomer graphs',[claim('a','explicit lactam graph','tautomer','O=c1cccc[nH]1')],'Oc1ccccn1','tautomer',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Hydrogen/bond-placement tautomer distinction retained.'),
case('D17','explicit isotope scope left open',[claim('a','ethanol isotope composition explicitly open','isotope',None,'UNSPECIFIED',framework='CCO')],'[13CH3]CO','isotope',['BROADER_THAN_CANDIDATE'],'RECONCILIATION_UNRESOLVED','Explicit open isotope scope; ordinary unlabelled ethanol is not asserted to mean all isotopologues.'),
case('D18','unknown keyword role',[claim('a','ethanol','constitution','CCO'),claim('b','unknown associated string','constitution',None,'UNKNOWN','SEARCH_LABEL',False)],'CCO','constitution',['EXACT_COMPATIBLE','UNKNOWN'],'RECONCILIATION_UNRESOLVED','Unestablished role cannot be silently ignored.'),
case('D19','achiral dimension proven irrelevant',[claim('a','ethanol graph','stereochemistry','CCO','NOT_APPLICABLE')],'OCC','stereochemistry',['NOT_APPLICABLE'],'RECONCILED_COMPATIBLE','Same constitution and no potential stereo.'),
case('D20','broad stereo cannot hide constitutional contradiction',[claim('a','dimethyl ether','constitution','COC'),claim('b','explicitly unspecified butan-2-ol stereo','stereochemistry',None,'UNSPECIFIED',framework=U)],'CCO','constitution',['EXACT_INCOMPATIBLE','UNKNOWN'],'RECONCILIATION_CONFLICT','Conflicts dominate unrelated broad/unknown claims.'),
case('D21','candidate-derived identifier',[claim('a','candidate-generated InChIKey','constitution','CCO',origin='CANDIDATE_DERIVED')],'CCO','constitution',['CANDIDATE_OBSERVATION_ONLY'],'RECONCILIATION_UNRESOLVED','Candidate-derived evidence cannot confirm itself.')]
held=[case('H01','positional isomers',[claim('a','explicit meta bromochlorobenzene graph','constitution','Brc1cccc(Cl)c1')],'Brc1ccc(Cl)cc1','constitution',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Different ring substitution.'),case('H02','acetic acid / acetate',[claim('a','acetate','protonation_charge','CC(=O)[O-]')],'CC(=O)O','protonation_charge',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Proton/charge distinction.'),case('H03','unspecified stereo on different scaffold',[claim('a','pentan-2-ol unspecified','stereochemistry',None,'UNSPECIFIED',framework='CCCC(O)C')],'CCC[C@H](O)C','stereochemistry',['BROADER_THAN_CANDIDATE'],'RECONCILIATION_UNRESOLVED','Broad source not exact.'),case('H04','equivalent traversal',[claim('a','explicit propan-1-ol graph','constitution','CCCO')],'OCCC','constitution',['EXACT_COMPATIBLE'],'RECONCILED_COMPATIBLE','Equivalent graph traversal.'),case('H05','unknown family scope',[claim('a','fatty alcohols','constitution',None,'UNKNOWN')],'CCCCO','constitution',['UNKNOWN'],'RECONCILIATION_UNRESOLVED','Family label does not select a member.'),case('H06','component stoichiometry',[claim('a','explicit two-water composition','component_stoichiometry','CCO.O.O')],'CCO.O','component_stoichiometry',['EXACT_INCOMPATIBLE'],'RECONCILIATION_CONFLICT','Defined component multiplicity differs.')]
dependent=case('H07','dependent parse is not an independent source vote',[claim('a','explicit ethanol graph','constitution','CCO'),claim('b','parser derivative','constitution','OCC',origin='DERIVED_SOURCE')],'CCO','constitution',['EXACT_COMPATIBLE','EXACT_COMPATIBLE'],'RECONCILED_COMPATIBLE','Dependent claims retain one lineage.');dependent['claims'][1]['dependencies']=['a'];held.append(dependent)
missing=case('H08','missing dependency',[claim('a','derived without parent','constitution','CCO',origin='DERIVED_SOURCE')],'CCO','constitution',['UNKNOWN'],'RECONCILIATION_UNRESOLVED','Missing dependency prevents using evidence.');missing['claims'][0]['dependencies']=['missing'];held.append(missing)
write(H/'controls/development_controls.json',{'review':'CHEMICAL_REVIEW_PENDING','cases':dev});write(H/'controls/heldout_controls.json',{'review':'CHEMICAL_REVIEW_PENDING','visibility':'PUBLIC_FROZEN_NOT_BLINDED','cases':held})
write(H/'controls/benchmark_freeze.json',{'version':'1.0','stage':'BEFORE_IMPLEMENTATION','sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in (H/'controls').glob('*.json')}})
paths=[B/n for n in ('resolver.py','source_form.py','form_characterizer.py','identity_comparator.py','providers.py','provider_capabilities.py','evidence_model.py','comptox.py','schema.sql','output/registry.sqlite','fresh_blinded_evaluation/run/candidates.sqlite')]
for folder in ('nsc_architecture_experiment','nsc002_experiment','charge_dimension_evidence'):
 paths += [p for p in (B/folder).rglob('*') if p.is_file() and p.suffix in ('.py','.json','.ebnf') and '__pycache__' not in str(p)]
write(H/'evaluation/pre_implementation_hashes.json',{'files':{str(p.relative_to(B)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}})
print('21 development and 8 public heldout controls frozen independently of CUMA.')
